-- GENERATED by scripts/generate-seed.mjs — publishes Mission 05 (Solar), 06 (Robot) and 07 (Home device).
-- For a database that already ran 003. Safe to run twice: a mission that is already published is skipped. Needs 001-006.

on conflict (slug) do nothing;

do $seed$
declare v_id uuid; v_status text;
begin
  select id, status into v_id, v_status from public.missions where slug = 'solar';
  if v_id is not null and v_status <> 'coming_soon' then
    raise notice 'mission solar already seeded - skipping';
    return;
  end if;
  if v_id is null then
    values ('solar', 5, '☀️', $j${"ha":"Hasken Rana","en":"Solar Energy"}$j$::jsonb,
            (select id from public.categories where slug = 'energy'),
            $j$["teach","show","practice","challenge","quiz","reward"]$j$::jsonb, $j${"teach":[10,"Resource Explorer"],"show":5,"practice":[10,"Young Inventor"],"sort":5,"safety":5,"business":[15,"Smart Builder"],"quiz":5,"finish":[10,"Solar Pioneer"]}$j$::jsonb, $j${"header_title":{"ha":"HASKEN RANA","en":"SOLAR ENERGY"},"mixed":true}$j$::jsonb, 'draft')
    returning id into v_id;
  else  -- was a "coming soon" placeholder: fill it in
    update public.missions set stages = $j$["teach","show","practice","challenge","quiz","reward"]$j$::jsonb, reward_rules = $j${"teach":[10,"Resource Explorer"],"show":5,"practice":[10,"Young Inventor"],"sort":5,"safety":5,"business":[15,"Smart Builder"],"quiz":5,"finish":[10,"Solar Pioneer"]}$j$::jsonb,
           engine_options = $j${"header_title":{"ha":"HASKEN RANA","en":"SOLAR ENERGY"},"mixed":true}$j$::jsonb, status = 'draft' where id = v_id;
  end if;
  -- publishing runs the Hausa+English completeness trigger; the seed fails loudly if anything is missing
  update public.missions set status = 'published' where id = v_id;
end $seed$;

