  ('Solar Pioneer', '🏅', $j${"ha":"Majagaba na Hasken Rana","en":"Solar Pioneer"}$j$::jsonb, $j${"ha":"Ka gama Aiki na 05","en":"Finish Mission 05"}$j$::jsonb, 0, $j${"granted_by":[{"mission":"solar","event":"finish"}]}$j$::jsonb),
