    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🔧","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"A wani ƙauye, dare yana yi duhu. Mutane suna kashe kuɗi da yawa a kan mai don samun haske.","en":"In a village the nights are dark. People spend a lot of money on fuel for light."}},{"text":{"ha":"Rana tana haskakawa kowace rana kyauta. Za ka iya taimaka mana mu yi amfani da ita?","en":"The sun shines every day for free. Can you help us use it?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Abu na asali da sabon abu","en":"Resource and new product"},"lines":[{"text":{"ha":"Hasken rana abu na asali ne. Yana fitowa daga yanayi, kyauta.","en":"Sunlight is a resource. It comes from nature, for free."}},{"text":{"ha":"Allon solar yana mai da shi wutar lantarki. Wannan sabon abu ne mai amfani.","en":"A solar panel turns it into electricity. That is a useful new product."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"☀️","title":{"ha":"Rana","en":"The sun"},"lines":[{"k":"whatIs","text":{"ha":"Rana tauraruwa ce mai ba da haske da zafi.","en":"The sun is a star that gives light and heat."}},{"k":"whatDoes","text":{"ha":"Tana ba da makamashi kyauta kowace rana.","en":"It gives free energy every day."}},{"k":"whyNeeded","text":{"ha":"Makamashin ba ya ƙarewa, kuma ba ya gurɓata iska.","en":"This energy does not run out and does not pollute the air."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Kada ka kalli rana kai tsaye. Yana cutar da idanu.","en":"Never look straight at the sun. It harms your eyes."}},{"text":{"ha":"Allon solar yana zafi a rana. Kada ka taɓa waya da aka bare ko soket na wutar gida. Manya ne kawai ke haɗa baturi da waya. Wannan wasa ne kawai.","en":"A solar panel gets hot in the sun. Never touch bare wires or mains sockets. Only adults connect batteries and wires. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🔆","title":{"ha":"Allon solar","en":"Solar panel"},"lines":[{"k":"whatIs","text":{"ha":"Faranti ne da ke ɗaukar hasken rana.","en":"A flat plate that catches sunlight."}},{"k":"whatDoes","text":{"ha":"Yana mai da hasken rana zuwa wutar lantarki.","en":"It turns sunlight into electricity."}},{"k":"whyNeeded","text":{"ha":"Don samun wuta ba tare da mai ko layin wuta ba.","en":"To get power without fuel or power lines."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🔋","title":{"ha":"Baturi","en":"Battery"},"lines":[{"k":"whatIs","text":{"ha":"Baturi yana adana wutar lantarki.","en":"A battery stores electricity."}},{"k":"whatDoes","text":{"ha":"Yana ba da wuta da dare, lokacin da babu rana.","en":"It gives power at night, when there is no sun."}},{"k":"whyNeeded","text":{"ha":"Don haske ya ci gaba bayan rana ta faɗi.","en":"So the light keeps going after the sun sets."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🎛️","title":{"ha":"Mai kula da caji","en":"Charge controller"},"lines":[{"k":"whatIs","text":{"ha":"Ƙaramar na’ura ce da ke kula da cajin baturi.","en":"A small device that looks after the battery charge."}},{"k":"whatDoes","text":{"ha":"Tana hana baturi cikawa fiye da kima.","en":"It stops the battery from overfilling."}},{"k":"whyNeeded","text":{"ha":"Don baturi ya daɗe kuma ya kasance lafiya.","en":"So the battery lasts long and stays safe."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"💡","title":{"ha":"Fitila da cajar waya","en":"Lamp and phone charger"},"lines":[{"k":"whatIs","text":{"ha":"Abubuwan da ke amfani da wutar lantarki.","en":"Things that use the electricity."}},{"k":"whatDoes","text":{"ha":"Fitila tana haskakawa. Cajar waya tana cika wayar.","en":"A lamp gives light. A charger fills a phone."}},{"k":"whyNeeded","text":{"ha":"Su ne dalilin gina tsarin: amfani.","en":"They are the reason we build the system: value."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Hasken rana kyauta ne, amma allon solar da baturi suna da farashi a farko.","en":"Sunlight is free, but the panel and battery cost money at the start."}},{"text":{"ha":"Bayan haka ba a kashe kuɗin mai. Ana iya sayar da fitilun solar ko cajin waya.","en":"After that there is no fuel to buy. Solar lamps or phone charging can be sold."}},{"text":{"ha":"Kowanne yana da hanyarsa. Wasu matakai na manya ne kawai. Za ka kalle su duka.","en":"Each has its own way. Some steps are for adults only. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'sun', 0, $j${"emoji":"☀️","name":{"ha":"Rana ta haskaka","en":"The sun shines"},"text":{"ha":"Rana tana aika hasken rana zuwa ƙasa.","en":"The sun sends sunlight down to the ground."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'panel', 1, $j${"emoji":"🔆","name":{"ha":"Allon solar ya ɗauki haske","en":"The panel catches light"},"text":{"ha":"Allon yana ɗaukar hasken rana ya mai da shi wuta.","en":"The panel catches sunlight and turns it into electricity."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ctrl', 2, $j${"emoji":"🎛️","name":{"ha":"Mai kula da caji","en":"Charge controller"},"text":{"ha":"Wutar tana wucewa ta mai kula da caji. Manya ne ke haɗa shi.","en":"The electricity passes through the charge controller. Adults connect it."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'battery', 3, $j${"emoji":"🔋","name":{"ha":"Baturi ya adana wuta","en":"The battery stores power"},"text":{"ha":"Baturi yana adana wutar don dare.","en":"The battery keeps the power for the night."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'lamp', 4, $j${"emoji":"💡","name":{"ha":"Fitila ta haska","en":"The lamp lights up"},"text":{"ha":"Da dare, baturi yana ba fitila wuta ta haska.","en":"At night the battery gives the lamp power to shine."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pplace', 5, $j${"emoji":"📍","name":{"ha":"Sanya allon a rana","en":"Put the panel in the sun"},"text":{"ha":"Ana sanya allon a wuri mai rana, ba inuwa.","en":"The panel goes in a sunny place, not in shade."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pcable', 6, $j${"emoji":"🔌","name":{"ha":"Haɗa kebul","en":"Connect the cable"},"text":{"ha":"Babba yana haɗa kebul ɗin cajar waya da allon.","en":"An adult connects the phone cable to the panel."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pcharge', 7, $j${"emoji":"📱","name":{"ha":"Waya tana caji","en":"The phone charges"},"text":{"ha":"Waya tana caji da hasken rana.","en":"The phone charges using sunlight."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'punplug', 8, $j${"emoji":"⏏️","name":{"ha":"Cire kebul","en":"Unplug the cable"},"text":{"ha":"Babba yana cire kebul idan waya ta cika.","en":"An adult unplugs the cable when the phone is full."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pstore', 9, $j${"emoji":"🏠","name":{"ha":"Ajiye allon","en":"Store the panel"},"text":{"ha":"Ana ajiye allon a wuri mai tsabta da bushewa.","en":"The panel is kept in a clean, dry place."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cspot', 10, $j${"emoji":"🌤️","name":{"ha":"Zaɓi wuri mai rana","en":"Choose a sunny spot"},"text":{"ha":"Wuri ba tare da inuwar bishiya ko gini ba.","en":"A place with no shade from trees or buildings."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ctilt', 11, $j${"emoji":"📐","name":{"ha":"Karkatar da allon","en":"Tilt the panel"},"text":{"ha":"Babba yana karkatar da allon zuwa sama, yana fuskantar kudu.","en":"An adult tilts the panel up, facing south."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cclean', 12, $j${"emoji":"🧽","name":{"ha":"Goge ƙura","en":"Wipe off dust"},"text":{"ha":"Idan allon bai da zafi, a goge ƙura da rigar laushi. Babba yana kusa.","en":"When the panel is cool, wipe off dust with a soft cloth. An adult is nearby."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ccheck', 13, $j${"emoji":"🔍","name":{"ha":"Duba waya","en":"Check the wires"},"text":{"ha":"Babba yana duba wayoyi da haɗin su.","en":"An adult checks the wires and connections."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'lamp', 0, $j${"id":"lamp","emoji":"💡","name":{"ha":"Fitilar solar","en":"Solar lamp"},"steps":["sun","panel","ctrl","battery","lamp"],"result":{"emoji":"💡","name":{"ha":"Fitilar solar","en":"Solar lamp"}},"summary":{"ha":"Fitilar solar: rana → allon → mai kula → baturi → fitila.","en":"Solar lamp: sun → panel → controller → battery → lamp."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'phone', 1, $j${"id":"phone","emoji":"📱","name":{"ha":"Cajin waya da rana","en":"Charging a phone with sun"},"steps":["pplace","pcable","pcharge","punplug","pstore"],"result":{"emoji":"📱","name":{"ha":"Cajin waya da rana","en":"Charging a phone with sun"}},"summary":{"ha":"Cajin waya: allon yana cikin rana, babba yana haɗa kebul. Ba a buƙatar baturi.","en":"Phone charging: the panel sits in the sun and an adult connects the cable. No battery needed."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'care', 2, $j${"id":"care","emoji":"🧽","name":{"ha":"Kula da allon solar","en":"Looking after a solar panel"},"steps":["cspot","ctilt","cclean","ccheck"],"result":{"emoji":"🔆","name":{"ha":"Allon solar lafiya","en":"A healthy solar panel"}},"summary":{"ha":"Kula da allo: wuri mai rana, karkata, goge ƙura, duba waya.","en":"Panel care: sunny spot, tilt, wipe dust, check wires."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"🌞","kind":"resource","name":{"ha":"Hasken rana","en":"Sunlight"},"why":{"ha":"Yana fitowa daga yanayi, kyauta. Abu na asali ne.","en":"It comes from nature, for free. It is a resource."}},{"emoji":"💡","kind":"product","name":{"ha":"Fitilar solar","en":"Solar lamp"},"why":{"ha":"An yi ta daga allon solar da baturi. Sabon abu ne.","en":"It is made from a panel and a battery. It is a new product."}},{"emoji":"💨","kind":"resource","name":{"ha":"Iska","en":"Wind"},"why":{"ha":"Iska tana fitowa daga yanayi. Abu na asali ne.","en":"Wind comes from nature. It is a resource."}},{"emoji":"📱","kind":"product","name":{"ha":"Waya da aka caji da rana","en":"A phone charged by the sun"},"why":{"ha":"Wutar rana ta zama amfani. Sakamako ne mai ƙima.","en":"Sun power became something useful. It is the valuable result."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"sort","key":"safety","ask":{"ha":"Wannan lafiya ne ko haɗari?","en":"Is this safe or dangerous?"},"options":[{"kind":"safe","icon":"✅","label":{"ha":"Lafiya","en":"Safe"}},{"kind":"danger","icon":"⚠️","label":{"ha":"Haɗari","en":"Dangerous"}}],"items":[{"emoji":"😎","kind":"danger","name":{"ha":"Kallon rana kai tsaye","en":"Looking straight at the sun"},"why":{"ha":"Yana cutar da idanu. Kada ka yi.","en":"It harms your eyes. Never do it."}},{"emoji":"🧽","kind":"safe","name":{"ha":"Goge ƙurar allo mai sanyi da rigar laushi (babba yana kusa)","en":"Wiping a cool panel with a soft cloth (adult nearby)"},"why":{"ha":"Wannan lafiya ne idan allon bai da zafi.","en":"This is safe when the panel is cool."}},{"emoji":"🔌","kind":"danger","name":{"ha":"Taɓa waya da aka bare","en":"Touching a bare wire"},"why":{"ha":"Wutar lantarki tana iya cutarwa. Ka gaya wa babba.","en":"Electricity can hurt you. Tell an adult."}},{"emoji":"💡","kind":"safe","name":{"ha":"Amfani da fitilar solar da dare","en":"Using a solar lamp at night"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🔋","kind":"danger","name":{"ha":"Wargaza baturi","en":"Taking a battery apart"},"why":{"ha":"Baturi yana da sinadari mai haɗari. Manya ne kawai.","en":"A battery holds harmful chemicals. Adults only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'challenge', 'business', 2, $j${"type":"business","key":"business"}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Menene allon solar ke yi?","en":"What does a solar panel do?"}$j$::jsonb, $j$[{"ha":"Yana mai da hasken rana wutar lantarki","en":"Turns sunlight into electricity"},{"ha":"Yana sa ruwan sama","en":"Makes rain"},{"ha":"Yana dafa abinci","en":"Cooks food"}]$j$::jsonb, 0, $j${"ha":"Allon solar yana ɗaukar hasken rana ya mai da shi wutar lantarki.","en":"A solar panel catches sunlight and turns it into electricity."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Me ya sa ba a kallon rana kai tsaye?","en":"Why do we never look straight at the sun?"}$j$::jsonb, $j$[{"ha":"Yana cutar da idanu","en":"It harms the eyes"},{"ha":"Yana da daɗi","en":"It is fun"},{"ha":"Yana sa sanyi","en":"It makes us cold"}]$j$::jsonb, 0, $j${"ha":"Hasken rana yana da ƙarfi sosai kuma yana cutar da idanu.","en":"Sunlight is very strong and harms the eyes."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Wane sashi ne yake adana wuta don dare?","en":"Which part stores power for the night?"}$j$::jsonb, $j$[{"ha":"Fitila","en":"Lamp"},{"ha":"Baturi","en":"Battery"},{"ha":"Rana","en":"Sun"}]$j$::jsonb, 1, $j${"ha":"Baturi yana adana wutar da allon ya samu, don a yi amfani da ita da dare.","en":"The battery keeps the power the panel made, for use at night."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Me ya sa muke da mai kula da caji?","en":"Why do we have a charge controller?"}$j$::jsonb, $j$[{"ha":"Don baturi kada ya cika fiye da kima","en":"So the battery does not overfill"},{"ha":"Don ya yi kyau","en":"To look nice"},{"ha":"Don ya sa rana ta haskaka","en":"To make the sun shine"}]$j$::jsonb, 0, $j${"ha":"Mai kula da caji yana kare baturi, don ya daɗe.","en":"The charge controller protects the battery so it lasts."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Wa ke haɗa baturi da waya?","en":"Who connects batteries and wires?"}$j$::jsonb, $j$[{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Manya","en":"Adults"},{"ha":"Babu kowa","en":"Nobody"}]$j$::jsonb, 1, $j${"ha":"Wutar lantarki tana iya cutarwa. Manya ne kawai ke haɗawa.","en":"Electricity can hurt. Only adults connect things."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"A ina ake sanya allon solar?","en":"Where do we put a solar panel?"}$j$::jsonb, $j$[{"ha":"A wuri mai rana, ba inuwa","en":"In a sunny place with no shade"},{"ha":"A cikin akwati","en":"Inside a box"},{"ha":"A ƙarƙashin bishiya","en":"Under a tree"}]$j$::jsonb, 0, $j${"ha":"Allon yana buƙatar haske kai tsaye, don haka a guji inuwa.","en":"The panel needs direct light, so avoid shade."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ake samun riba?","en":"How do we find profit?"}$j$::jsonb, $j$[{"ha":"Farashin sayarwa − kuɗin da aka kashe","en":"Selling price − money spent"},{"ha":"Farashin sayarwa + kuɗin da aka kashe","en":"Selling price + money spent"},{"ha":"Kuɗin ƙunshewa kaɗai","en":"Packaging cost only"}]$j$::jsonb, 0, $j${"ha":"Riba = farashin sayarwa − jimillar kuɗin da aka kashe.","en":"Profit = selling price − total money spent."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🏫","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"A makaranta, malama tana son ƙaramin mutum-mutumi (robot) da zai taimaka a aji.","en":"At school a teacher wants a small robot to help in class."}},{"text":{"ha":"Za ka iya koyon yadda ake gina shi ka taimaka mata?","en":"Can you learn how to build one and help her?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🤖","title":{"ha":"Menene mutum-mutumi?","en":"What is a robot?"},"lines":[{"text":{"ha":"Mutum-mutumi na’ura ce da ke gani ko ji, tunani, sannan ta yi aiki.","en":"A robot is a machine that senses, thinks, and then acts."}},{"text":{"ha":"Gani/Ji → Tunani → Aiki","en":"Sense → Think → Act"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Yi amfani da ƙananan baturi kawai (kamar AA). Kada ka taɓa wutar gida (soket).","en":"Use only small batteries (like AA). Never touch mains sockets."}},{"text":{"ha":"Kada ka haɗa gefen baturi biyu da waya kai tsaye: zai yi zafi sosai. Manya ne kawai ke yanka, ko amfani da manne mai zafi ko solder. Wannan wasa ne kawai.","en":"Never join both ends of a battery with a wire: it gets very hot. Only adults cut, or use hot glue or soldering. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"🔋","title":{"ha":"Baturi","en":"Battery"},"lines":[{"k":"whatIs","text":{"ha":"Ƙaramin akwati da ke adana wuta.","en":"A small container that stores power."}},{"k":"whatDoes","text":{"ha":"Yana ba mutum-mutumi wutar da yake buƙata.","en":"It gives the robot the power it needs."}},{"k":"whyNeeded","text":{"ha":"Ba tare da wuta ba, babu sashin da zai yi aiki.","en":"Without power nothing can work."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🔌","title":{"ha":"Waya da maɓalli","en":"Wires and switch"},"lines":[{"k":"whatIs","text":{"ha":"Waya hanya ce ta wuta. Maɓalli yana buɗewa ko rufe hanyar.","en":"A wire is a path for power. A switch opens or closes the path."}},{"k":"whatDoes","text":{"ha":"Maɓalli yana kunnawa da kashewa.","en":"The switch turns the robot on and off."}},{"k":"whyNeeded","text":{"ha":"Don mu iya sarrafa mutum-mutumi da tsaro.","en":"So we can control the robot safely."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"⚙️","title":{"ha":"Injin","en":"Motor"},"lines":[{"k":"whatIs","text":{"ha":"Ƙaramar na’ura da ke juyawa idan ta samu wuta.","en":"A small machine that spins when it gets power."}},{"k":"whatDoes","text":{"ha":"Yana juya ƙafafu.","en":"It turns the wheels."}},{"k":"whyNeeded","text":{"ha":"Shi ne yake sa mutum-mutumi ya motsa.","en":"It is what makes the robot move."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🛞","title":{"ha":"Ƙafafu da jiki","en":"Wheels and body"},"lines":[{"k":"whatIs","text":{"ha":"Ƙafafu suna juyawa. Jiki yana ɗaukar dukkan sassa.","en":"Wheels roll. The body holds all the parts."}},{"k":"whatDoes","text":{"ha":"Ƙafafu suna kai mutum-mutumi wuri.","en":"Wheels carry the robot along."}},{"k":"whyNeeded","text":{"ha":"Jiki mai ƙarfi yana kare sassan.","en":"A strong body protects the parts."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"👁️","title":{"ha":"Na’urar ji (sensor)","en":"Sensor"},"lines":[{"k":"whatIs","text":{"ha":"Na’ura ce da ke gane abu, kamar cikas ko haske.","en":"A part that notices things, like an obstacle or light."}},{"k":"whatDoes","text":{"ha":"Tana gaya wa kwakwalwa abin da ta gani.","en":"It tells the brain what it noticed."}},{"k":"whyNeeded","text":{"ha":"Don mutum-mutumi kada ya buga bango.","en":"So the robot does not bump into walls."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"🧠","title":{"ha":"Kwakwalwa (controller)","en":"Brain (controller)"},"lines":[{"k":"whatIs","text":{"ha":"Ƙaramar kwamfuta ce a cikin mutum-mutumi.","en":"A tiny computer inside the robot."}},{"k":"whatDoes","text":{"ha":"Tana yanke shawara bisa abin da na’urar ji ta gaya mata.","en":"It decides using what the sensor tells it."}},{"k":"whyNeeded","text":{"ha":"Ita ce ke sa mutum-mutumi ya yi tunani.","en":"It is what lets the robot “think”."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 9, $j${"emoji":"💰","title":{"ha":"Fasaha tana ƙara ƙima","en":"Skills add value"},"lines":[{"text":{"ha":"Mutum-mutumi na iya ɗaukar kaya, tsaftacewa ko koyar da yara.","en":"Robots can carry things, clean, or teach children."}},{"text":{"ha":"Mai gina su yana samun ilimi da aiki. Kowanne yana da hanyarsa. Wasu matakai na manya ne. Za ka kalle su duka.","en":"People who build them gain skills and jobs. Each has its own way. Some steps are for adults. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pbat', 0, $j${"emoji":"🔋","name":{"ha":"Baturi","en":"Battery"},"text":{"ha":"Baturi yana ba da wuta.","en":"The battery gives power."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pwire', 1, $j${"emoji":"🔌","name":{"ha":"Waya","en":"Wires"},"text":{"ha":"Waya tana ɗaukar wutar daga baturi.","en":"Wires carry the power from the battery."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pswitch', 2, $j${"emoji":"🔘","name":{"ha":"Maɓalli","en":"Switch"},"text":{"ha":"Idan an kunna maɓalli, hanyar wutar ta cika.","en":"When the switch is on, the path for power is complete."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pmotor', 3, $j${"emoji":"⚙️","name":{"ha":"Injin ya juya","en":"The motor spins"},"text":{"ha":"Injin yana karɓar wuta ya fara juyawa.","en":"The motor gets power and starts to spin."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pwheel', 4, $j${"emoji":"🛞","name":{"ha":"Ƙafa ta juya","en":"The wheel turns"},"text":{"ha":"Injin yana juya ƙafa, sai mutum-mutumi ya ci gaba.","en":"The motor turns the wheel and the robot moves."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bsense', 5, $j${"emoji":"👁️","name":{"ha":"Na’urar ji ta ga cikas","en":"The sensor sees an obstacle"},"text":{"ha":"Na’urar ji ta ga akwai abu a gaba.","en":"The sensor notices something in front."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bthink', 6, $j${"emoji":"🧠","name":{"ha":"Kwakwalwa ta yanke shawara","en":"The brain decides"},"text":{"ha":"Kwakwalwa tana cewa: a tsaya a juya.","en":"The brain decides: stop and turn."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bact', 7, $j${"emoji":"🔄","name":{"ha":"Injin ya juya hanya","en":"The motor turns away"},"text":{"ha":"Injin yana juya mutum-mutumi zuwa wata hanya.","en":"The motor turns the robot another way."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bgo', 8, $j${"emoji":"➡️","name":{"ha":"Ya ci gaba","en":"The robot goes on"},"text":{"ha":"Mutum-mutumi ya ci gaba ba tare da bugu ba.","en":"The robot goes on without bumping."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'rplan', 9, $j${"emoji":"✏️","name":{"ha":"Zana tsari","en":"Draw the plan"},"text":{"ha":"Ana zana yadda mutum-mutumi zai yi kama.","en":"Draw what the robot will look like."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'rparts', 10, $j${"emoji":"🧰","name":{"ha":"Tara sassa","en":"Collect the parts"},"text":{"ha":"Ana tara sassan kit: injin, ƙafafu, baturi, waya, maɓalli.","en":"Collect the kit parts: motor, wheels, battery, wires, switch."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'rframe', 11, $j${"emoji":"🔧","name":{"ha":"Gyara injin a jiki","en":"Fix the motor to the body"},"text":{"ha":"Babba yana gyara injin a jikin mutum-mutumi.","en":"An adult fixes the motor to the robot body."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'rwheel', 12, $j${"emoji":"🛞","name":{"ha":"Saka ƙafafu","en":"Attach the wheels"},"text":{"ha":"Ana saka ƙafafu a kan injin.","en":"Attach the wheels to the motor."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'rbat', 13, $j${"emoji":"🔋","name":{"ha":"Haɗa baturi","en":"Connect the battery"},"text":{"ha":"Babba yana haɗa baturi da maɓalli.","en":"An adult connects the battery and the switch."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'rtest', 14, $j${"emoji":"✅","name":{"ha":"Gwada a ƙasa","en":"Test on the floor"},"text":{"ha":"Ana kunna maɓalli a gwada a ƙasa mai tsabta.","en":"Switch it on and test on a clean floor."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'power', 0, $j${"id":"power","emoji":"🔋","name":{"ha":"Yadda wuta ke tafiya","en":"How power travels"},"steps":["pbat","pwire","pswitch","pmotor","pwheel"],"result":{"emoji":"🚗","name":{"ha":"Mutum-mutumi yana tafiya","en":"A moving robot"}},"summary":{"ha":"Wuta tana fita daga baturi ta waya da maɓalli zuwa injin.","en":"Power goes from the battery through wires and the switch to the motor."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'brain', 1, $j${"id":"brain","emoji":"🧠","name":{"ha":"Yadda mutum-mutumi ke yanke shawara","en":"How a robot decides"},"steps":["bsense","bthink","bact","bgo"],"result":{"emoji":"🤖","name":{"ha":"Mutum-mutumi mai hankali","en":"A smart robot"}},"summary":{"ha":"Gani → Tunani → Aiki, ana maimaitawa.","en":"Sense → Think → Act, again and again."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'car', 2, $j${"id":"car","emoji":"🚗","name":{"ha":"Gina ƙaramar mota","en":"Building a toy robot car"},"steps":["rplan","rparts","rframe","rwheel","rbat","rtest"],"result":{"emoji":"🚗","name":{"ha":"Ƙaramar motar mutum-mutumi","en":"A toy robot car"}},"summary":{"ha":"Gina mota: zana, tara sassa, babba yana haɗa injin da baturi, sai a gwada.","en":"Car build: plan, parts, an adult fits the motor and battery, then test."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","ask":{"ha":"Wane aiki wannan sashi yake yi?","en":"What job does this part do?"},"options":[{"kind":"power","icon":"⚡","label":{"ha":"Wuta","en":"Power"}},{"kind":"move","icon":"🏃","label":{"ha":"Motsi","en":"Movement"}},{"kind":"brain","icon":"🧠","label":{"ha":"Ji da tunani","en":"Sensing and thinking"}}],"items":[{"emoji":"🔋","kind":"power","name":{"ha":"Baturi","en":"Battery"},"why":{"ha":"Baturi yana ba da wuta.","en":"The battery gives power."}},{"emoji":"⚙️","kind":"move","name":{"ha":"Injin","en":"Motor"},"why":{"ha":"Injin yana juyawa yana motsa mutum-mutumi.","en":"The motor spins and moves the robot."}},{"emoji":"🛞","kind":"move","name":{"ha":"Ƙafafu","en":"Wheels"},"why":{"ha":"Ƙafafu suna kai mutum-mutumi wuri.","en":"Wheels carry the robot along."}},{"emoji":"👁️","kind":"brain","name":{"ha":"Na’urar ji","en":"Sensor"},"why":{"ha":"Na’urar ji tana gane abubuwa.","en":"The sensor notices things."}},{"emoji":"🧠","kind":"brain","name":{"ha":"Kwakwalwa","en":"Controller"},"why":{"ha":"Kwakwalwa tana yanke shawara.","en":"The controller makes decisions."}},{"emoji":"🔌","kind":"power","name":{"ha":"Waya","en":"Wires"},"why":{"ha":"Waya tana ɗaukar wutar zuwa sassan.","en":"Wires carry power to the parts."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"🔘","kind":"safe","name":{"ha":"Danna maɓallin mutum-mutumin da aka gama","en":"Pressing the switch of a finished robot"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🎨","kind":"safe","name":{"ha":"Yi wa jikin mutum-mutumi ado da lambobi","en":"Decorating the robot body with stickers"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"✂️","kind":"adult","name":{"ha":"Yanka filastik da wuƙa","en":"Cutting plastic with a knife"},"why":{"ha":"Wuƙa tana da kaifi. Babba ne kawai.","en":"Knives are sharp. Only an adult."}},{"emoji":"🔥","kind":"adult","name":{"ha":"Amfani da manne mai zafi ko solder","en":"Using hot glue or a soldering iron"},"why":{"ha":"Suna ƙonewa. Babba ne kawai.","en":"They burn. Only an adult."}},{"emoji":"⚡","kind":"adult","name":{"ha":"Haɗa gefen baturi biyu da waya","en":"Joining both ends of a battery with a wire"},"why":{"ha":"Waya za ta yi zafi sosai. Kada ka yi, ka gaya wa babba.","en":"The wire gets very hot. Never do it; tell an adult."}}]}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Wane sashi ne yake ba da wuta?","en":"Which part gives power?"}$j$::jsonb, $j$[{"ha":"Baturi","en":"Battery"},{"ha":"Ƙafa","en":"Wheel"},{"ha":"Jiki","en":"Body"}]$j$::jsonb, 0, $j${"ha":"Baturi yana ba da wuta ga sauran sassan.","en":"The battery gives power to the other parts."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Menene injin yake yi?","en":"What does the motor do?"}$j$::jsonb, $j$[{"ha":"Yana juyawa idan ya samu wuta","en":"It spins when it gets power"},{"ha":"Yana adana wuta","en":"It stores power"},{"ha":"Yana ganin abu","en":"It sees things"}]$j$::jsonb, 0, $j${"ha":"Injin yana juya ƙafafu har mutum-mutumi ya motsa.","en":"The motor turns the wheels so the robot moves."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Wane ne daidai tsarin mutum-mutumi?","en":"What is the right order for a robot?"}$j$::jsonb, $j$[{"ha":"Aiki → Tunani → Gani","en":"Act → Think → Sense"},{"ha":"Gani → Tunani → Aiki","en":"Sense → Think → Act"},{"ha":"Tunani → Aiki → Gani","en":"Think → Act → Sense"}]$j$::jsonb, 1, $j${"ha":"Mutum-mutumi yana gani, sannan yana tunani, sannan yana aiki.","en":"A robot senses first, then thinks, then acts."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Wane sashi ne yake yanke shawara?","en":"Which part makes decisions?"}$j$::jsonb, $j$[{"ha":"Kwakwalwa (controller)","en":"The brain (controller)"},{"ha":"Waya","en":"Wires"},{"ha":"Ƙafa","en":"Wheel"}]$j$::jsonb, 0, $j${"ha":"Kwakwalwa tana amfani da abin da na’urar ji ta gaya mata.","en":"The controller uses what the sensor tells it."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Wa ke yanka filastik da wuƙa?","en":"Who cuts plastic with a knife?"}$j$::jsonb, $j$[{"ha":"Babba","en":"An adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa","en":"Anyone"}]$j$::jsonb, 0, $j${"ha":"Wuƙa tana da kaifi. Babba ne kawai.","en":"Knives are sharp. Only an adult."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Me yake faruwa idan an kashe maɓalli?","en":"What happens when the switch is off?"}$j$::jsonb, $j$[{"ha":"Hanyar wuta ta katse","en":"The path for power is broken"},{"ha":"Injin yana ƙara sauri","en":"The motor speeds up"},{"ha":"Baturi ya cika","en":"The battery fills up"}]$j$::jsonb, 0, $j${"ha":"Maɓalli a kashe yana katse hanyar wuta, sai injin ya tsaya.","en":"An off switch breaks the path, so the motor stops."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Me ya sa ba ma haɗa gefen baturi biyu da waya?","en":"Why do we never join both ends of a battery with a wire?"}$j$::jsonb, $j$[{"ha":"Waya za ta yi zafi sosai","en":"The wire gets very hot"},{"ha":"Zai yi kyau","en":"It looks nice"},{"ha":"Yana ƙara wuta","en":"It adds power"}]$j$::jsonb, 0, $j${"ha":"Wutar tana gudu da yawa, waya ta ƙone. Ka gaya wa babba.","en":"Too much power flows and the wire burns. Tell an adult."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🔧","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"A wani gida, abinci yana lalacewa da sauri, ba a wanke hannu sosai, kuma shuka tana bushewa.","en":"In one home food spoils fast, hands are not washed well, and plants dry up."}},{"text":{"ha":"Za ka iya taimaka musu ka ƙirƙiri na’urori masu warware matsalolin?","en":"Can you help them invent devices to solve these problems?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🔍","title":{"ha":"Yadda mai ƙirƙira yake aiki","en":"How an inventor works"},"lines":[{"text":{"ha":"Mai ƙirƙira yana farawa da matsala, ba da na’ura ba.","en":"An inventor starts with a problem, not with a machine."}},{"text":{"ha":"Gano matsala → Tunani → Tsara → Gina → Gwada → Gyara","en":"Find a problem → Imagine → Plan → Build → Test → Improve"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Manya ne kawai ke yanka, huda, amfani da wuta ko dafa ruwa.","en":"Only adults cut, drill, use fire or boil water."}},{"text":{"ha":"Kada ka yi amfani da kwalba da aka sa sinadari ko magani a ciki. Kada ka taɓa gilashi da ya karye. Wannan wasa ne kawai.","en":"Never use a bottle that held chemicals or medicine. Never touch broken glass. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"🏺","title":{"ha":"Na’urar sanyaya abinci ta tukwane biyu","en":"Pot-in-pot cooler"},"lines":[{"k":"whatIs","text":{"ha":"Tukwane biyu na yumɓu, ɗaya a cikin ɗaya, da yashi mai ɗanshi a tsakani.","en":"Two clay pots, one inside the other, with wet sand between them."}},{"k":"whatDoes","text":{"ha":"Tana sanyaya abinci ba tare da wutar lantarki ba.","en":"It keeps food cool without electricity."}},{"k":"whyNeeded","text":{"ha":"Ruwa yana ƙafewa ya ɗauki zafi, abinci kuma yana daɗewa.","en":"Water dries up and takes the heat away, so food lasts longer."}},{"k":"fact","text":{"ha":"Wani malamin Najeriya, Mohammed Bah Abba, ya shahara da wannan ƙirƙira.","en":"A Nigerian teacher, Mohammed Bah Abba, became famous for this invention."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🚰","title":{"ha":"Wurin wanke hannu mai ƙafa","en":"Foot-pedal hand-washing station"},"lines":[{"k":"whatIs","text":{"ha":"Jarka mai ƙaramin rami da igiya da allon taka.","en":"A jerrycan with a small hole, a string and a foot pedal."}},{"k":"whatDoes","text":{"ha":"Idan ka taka, ruwa yana zubowa. Ba sai ka taɓa famfo ba.","en":"When you step, water flows. You do not touch a tap."}},{"k":"whyNeeded","text":{"ha":"Wanke hannu yana kare mu daga cututtuka.","en":"Washing hands protects us from sickness."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"💧","title":{"ha":"Kwalbar ban ruwa","en":"Bottle drip watering"},"lines":[{"k":"whatIs","text":{"ha":"Kwalba mai ruwa da ƙaramin rami a murfi, an juye a ƙasa.","en":"A water bottle with a tiny hole in the cap, set upside down in the soil."}},{"k":"whatDoes","text":{"ha":"Tana ba shuka ruwa a hankali.","en":"It waters the plant slowly."}},{"k":"whyNeeded","text":{"ha":"Ba a ɓatar da ruwa, shuka kuma ba ta bushewa.","en":"No water is wasted and the plant does not dry up."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"💰","title":{"ha":"Ƙirƙira tana ƙara ƙima","en":"Inventions add value"},"lines":[{"text":{"ha":"Na’ura mai warware matsala ana iya amfani da ita a gida ko a sayar.","en":"A device that solves a problem can be used at home or sold."}},{"text":{"ha":"Kowanne yana da hanyarsa. Wasu matakai na manya ne kawai. Za ka kalle su duka.","en":"Each has its own way. Some steps are for adults only. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'gfind', 0, $j${"emoji":"🔍","name":{"ha":"Gano matsala","en":"Find a problem"},"text":{"ha":"Ana duba gida a gano abin da ke damun mutane.","en":"Look around and find what bothers people."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'gask', 1, $j${"emoji":"🗣️","name":{"ha":"Tambayi mutane","en":"Ask people"},"text":{"ha":"Ana tambayar iyali yadda matsalar take.","en":"Ask the family how the problem affects them."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'gidea', 2, $j${"emoji":"💡","name":{"ha":"Yi tunanin mafita","en":"Think of ideas"},"text":{"ha":"Ana tunanin hanyoyi da yawa, har da masu sauƙi.","en":"Think of many ways, including simple ones."},"kid":true}$j$::jsonb);
