  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","ask":{"ha":"Wannan matsala ce ko mafita?","en":"Is this a problem or a solution?"},"options":[{"kind":"problem","icon":"🔍","label":{"ha":"Matsala","en":"Problem"}},{"kind":"solution","icon":"💡","label":{"ha":"Mafita","en":"Solution"}}],"items":[{"emoji":"🍅","kind":"problem","name":{"ha":"Abinci yana lalacewa da sauri","en":"Food spoils fast"},"why":{"ha":"Wannan matsala ce da ake buƙatar warwarewa.","en":"This is a problem that needs solving."}},{"emoji":"🏺","kind":"solution","name":{"ha":"Tukwane biyu masu sanyaya abinci","en":"Pot-in-pot cooler"},"why":{"ha":"Wannan mafita ce ga lalacewar abinci.","en":"This is a solution to food spoiling."}},{"emoji":"🤲","kind":"problem","name":{"ha":"Ƙazantar hannu tana yaɗa cuta","en":"Dirty hands spread sickness"},"why":{"ha":"Wannan matsala ce.","en":"This is a problem."}},{"emoji":"🚰","kind":"solution","name":{"ha":"Wurin wanke hannu mai ƙafa","en":"Foot-pedal hand-washing station"},"why":{"ha":"Wannan mafita ce ga ƙazantar hannu.","en":"This is a solution to dirty hands."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"🍅","kind":"safe","name":{"ha":"Saka tumatur a ƙaramar tukunya","en":"Putting tomatoes in the small pot"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🌱","kind":"safe","name":{"ha":"Duba shuka da kwalbar ban ruwa","en":"Checking the plant with the drip bottle"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🔪","kind":"adult","name":{"ha":"Yanka ko huda jarka","en":"Cutting or drilling a jerrycan"},"why":{"ha":"Kayan huda suna da kaifi. Babba ne kawai.","en":"Drills and knives are sharp. Only an adult."}},{"emoji":"♨️","kind":"adult","name":{"ha":"Dafa ruwa ko amfani da wuta","en":"Boiling water or using fire"},"why":{"ha":"Zafi yana ƙonewa. Babba ne kawai.","en":"Heat burns. Only an adult."}},{"emoji":"🧪","kind":"adult","name":{"ha":"Amfani da tsohuwar kwalbar sinadari","en":"Using an old chemical bottle"},"why":{"ha":"Kada ka taɓa ta. Ka gaya wa babba.","en":"Do not touch it. Tell an adult."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'challenge', 'business', 2, $j${"type":"business","key":"business"}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Daga ina mai ƙirƙira yake farawa?","en":"Where does an inventor start?"}$j$::jsonb, $j$[{"ha":"Daga matsala","en":"With a problem"},{"ha":"Daga na’ura mai tsada","en":"With an expensive machine"},{"ha":"Daga hutu","en":"With a rest"}]$j$::jsonb, 0, $j${"ha":"Mai ƙirƙira yana farawa da gano matsala.","en":"An inventor starts by finding a problem."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Me ya sa tukwane biyu ke sanyaya abinci?","en":"Why does the pot-in-pot cooler keep food cool?"}$j$::jsonb, $j$[{"ha":"Ruwan da ke ƙafewa yana ɗaukar zafi","en":"Evaporating water takes the heat away"},{"ha":"Yana da wutar lantarki","en":"It has electricity"},{"ha":"Yana da kankara","en":"It has ice"}]$j$::jsonb, 0, $j${"ha":"Yashi mai ɗanshi yana ƙafewa, ya ɗauki zafi, abinci ya yi sanyi.","en":"Wet sand dries up and takes heat away, so the food stays cool."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Wa ke huda jarka?","en":"Who drills the jerrycan?"}$j$::jsonb, $j$[{"ha":"Babba","en":"An adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa","en":"Anyone"}]$j$::jsonb, 0, $j${"ha":"Kayan huda suna da kaifi. Babba ne kawai.","en":"Drills are sharp. Only an adult."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Me ya sa wurin wanke hannu yake da amfani?","en":"Why is a hand-washing station useful?"}$j$::jsonb, $j$[{"ha":"Yana kare mu daga cututtuka","en":"It protects us from sickness"},{"ha":"Yana sa hannu su yi ƙazanta","en":"It makes hands dirty"},{"ha":"Yana sa ruwa ya ƙare","en":"It uses up the water"}]$j$::jsonb, 0, $j${"ha":"Wanke hannu da sabulu yana kashe ƙwayoyin cuta.","en":"Washing with soap removes germs."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Wane ne ba a soya shi ko dafa shi a wannan darasin?","en":"Which device uses no fire at all in this lesson?"}$j$::jsonb, $j$[{"ha":"Tukwane biyu masu sanyaya","en":"Pot-in-pot cooler"},{"ha":"Dafa ruwa","en":"Boiling water"},{"ha":"Soya abinci","en":"Frying food"}]$j$::jsonb, 0, $j${"ha":"Tukwane biyu suna amfani da yashi mai ɗanshi ne kawai, babu wuta.","en":"The pot cooler uses only wet sand. There is no fire."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Wane ne “mafita” ga ƙazantar hannu?","en":"Which is a “solution” to dirty hands?"}$j$::jsonb, $j$[{"ha":"Wurin wanke hannu mai ƙafa","en":"A hand-washing station"},{"ha":"Jefar da sabulu","en":"Throwing away the soap"},{"ha":"Rufe famfo","en":"Closing the tap"}]$j$::jsonb, 0, $j${"ha":"Mafita tana warware matsala. Wurin wanke hannu yana warware ƙazanta.","en":"A solution fixes a problem. A hand-washing station fixes dirty hands."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ake samun riba?","en":"How do we find profit?"}$j$::jsonb, $j$[{"ha":"Farashin sayarwa − kuɗin da aka kashe","en":"Selling price − money spent"},{"ha":"Farashin sayarwa + kuɗin da aka kashe","en":"Selling price + money spent"},{"ha":"Kuɗin ƙunshewa kaɗai","en":"Packaging cost only"}]$j$::jsonb, 0, $j${"ha":"Riba = farashin sayarwa − jimillar kuɗin da aka kashe.","en":"Profit = selling price − total money spent."}$j$::jsonb, 5);
